import React, { useState, useEffect, useMemo, useCallback } from "react";
import { Task, TaskQueueStats } from "../types/api";
import "../animations.css";
import { 
  TasksIcon, 
  ClockIcon, 
  ProcessingIcon, 
  CheckIcon, 
  AlertIcon,
  CloseIcon
} from "./Icons";

interface TasksViewProps {}

interface TaskWithDetails extends Task {
  worker_name?: string;
  progress?: number;
  estimated_completion?: string;
}

interface TaskFilters {
  status: string;
  priority: string;
  task_type: string;
  worker: string;
  search: string;
}

const TasksView: React.FC<TasksViewProps> = () => {
  const [tasks, setTasks] = useState<TaskWithDetails[]>([]);
  const [queueStats, setQueueStats] = useState<TaskQueueStats | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [refreshInterval, setRefreshInterval] = useState<number>(5000);
  const [selectedTask, setSelectedTask] = useState<TaskWithDetails | null>(null);
  const [showTaskModal, setShowTaskModal] = useState<boolean>(false);
  const [isInitialLoad, setIsInitialLoad] = useState<boolean>(true); // Для контролю анімацій
  const [filters, setFilters] = useState<TaskFilters>({
    status: "all",
    priority: "all",
    task_type: "all",
    worker: "all",
    search: "",
  });

  // Функція для отримання порожніх статистик
  const getEmptyQueueStats = useCallback((): TaskQueueStats => {
    return {
      total_tasks: 0,
      pending_tasks: 0,
      processing_tasks: 0,
      completed_tasks: 0,
      failed_tasks: 0,
      average_processing_time: 0,
      queue_sizes: {
        critical: 0,
        high: 0,
        normal: 0,
        low: 0,
      },
      worker_distribution: {},
    };
  }, []);

  useEffect(() => {
    const fetchTasksData = async (isRefresh = false) => {
      try {
        // Показуємо loading тільки при першому завантаженні
        if (!isRefresh) {
          setLoading(true);
        }

        // Отримуємо реальні дані з API
        try {
          const [tasksResponse, statsResponse] = await Promise.all([
            fetch("/dashboard/api/tasks"),
            fetch("/dashboard/api/tasks/stats")
          ]);

          if (tasksResponse.ok && statsResponse.ok) {
            const tasksData = await tasksResponse.json();
            const statsData = await statsResponse.json();

            setTasks(tasksData.tasks || []);
            setQueueStats(statsData);
            setError(null);
          } else {
            // API повернув помилку
            setTasks([]);
            setQueueStats(getEmptyQueueStats());
            setError(`Помилка API: ${tasksResponse.status} ${tasksResponse.statusText}`);
          }
        } catch (apiError) {
          console.error("Помилка підключення до API:", apiError);
          setTasks([]);
          setQueueStats(getEmptyQueueStats());
          setError(`Не вдається підключитися до API: ${apiError instanceof Error ? apiError.message : String(apiError)}`);
        }
      } catch (err) {
        setError(`Помилка отримання даних: ${err instanceof Error ? err.message : String(err)}`);
        setTasks([]);
        setQueueStats(getEmptyQueueStats());
      } finally {
        if (!isRefresh) {
          setLoading(false);
          setIsInitialLoad(false); // Позначаємо, що початкове завантаження завершено
        }
      }
    };

    // Перше завантаження
    fetchTasksData(false);

    // Налаштовуємо інтервал для оновлення (без loading state)
    const interval = setInterval(() => fetchTasksData(true), refreshInterval);
    return () => clearInterval(interval);
  }, [refreshInterval, getEmptyQueueStats]);

  // Фільтрація завдань
  const filteredTasks = useMemo(() => {
    return tasks.filter(task => {
      if (filters.status !== "all" && task.status !== filters.status) return false;
      if (filters.priority !== "all" && task.priority !== filters.priority) return false;
      if (filters.task_type !== "all" && task.task_type !== filters.task_type) return false;
      if (filters.worker !== "all" && task.assigned_worker !== filters.worker) return false;
      if (filters.search && !task.task_id.toLowerCase().includes(filters.search.toLowerCase()) &&
          !task.task_type.toLowerCase().includes(filters.search.toLowerCase())) return false;
      return true;
    });
  }, [tasks, filters]);

  // Отримання унікальних значень для фільтрів
  const uniqueWorkers = useMemo(() => {
    const workers = tasks.map(t => t.assigned_worker).filter(Boolean) as string[];
    return Array.from(new Set(workers));
  }, [tasks]);

  const uniqueTaskTypes = useMemo(() => {
    return Array.from(new Set(tasks.map(t => t.task_type)));
  }, [tasks]);

  // Функції для управління завданнями
  const handleCancelTask = async (taskId: string) => {
    try {
      const response = await fetch(`/dashboard/api/tasks/${taskId}/cancel`, { method: 'POST' });
      if (response.ok) {
        setTasks(prev => prev.map(task => 
          task.task_id === taskId ? { ...task, status: 'cancelled' as const } : task
        ));
      } else {
        console.error('Помилка скасування завдання:', response.statusText);
      }
    } catch (err) {
      console.error('Помилка скасування завдання:', err);
    }
  };

  const handleRetryTask = async (taskId: string) => {
    try {
      const response = await fetch(`/dashboard/api/tasks/${taskId}/retry`, { method: 'POST' });
      if (response.ok) {
        setTasks(prev => prev.map(task => 
          task.task_id === taskId ? { ...task, status: 'pending' as const, retry_count: task.retry_count + 1 } : task
        ));
      } else {
        console.error('Помилка повтору завдання:', response.statusText);
      }
    } catch (err) {
      console.error('Помилка повтору завдання:', err);
    }
  };

  const handleClearQueue = async (priority: string) => {
    try {
      const response = await fetch(`/dashboard/api/tasks/clear-queue`, { 
        method: 'POST', 
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ priority })
      });
      if (response.ok) {
        setTasks(prev => prev.filter(task => 
          !(task.priority === priority && ['pending', 'assigned'].includes(task.status))
        ));
      } else {
        console.error('Помилка очищення черги:', response.statusText);
      }
    } catch (err) {
      console.error('Помилка очищення черги:', err);
    }
  };

  // Функції для отримання стилів
  const getStatusColor = (status: Task['status']) => {
    switch (status) {
      case 'pending': return 'bg-yellow-100 text-yellow-800';
      case 'assigned': return 'bg-blue-100 text-blue-800';
      case 'processing': return 'bg-purple-100 text-purple-800';
      case 'completed': return 'bg-green-100 text-green-800';
      case 'failed': return 'bg-red-100 text-red-800';
      case 'timeout': return 'bg-orange-100 text-orange-800';
      case 'retry': return 'bg-indigo-100 text-indigo-800';
      case 'cancelled': return 'bg-gray-100 text-gray-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getPriorityColor = (priority: Task['priority']) => {
    switch (priority) {
      case 'critical': return 'bg-red-500';
      case 'high': return 'bg-orange-500';
      case 'normal': return 'bg-blue-500';
      case 'low': return 'bg-green-500';
      default: return 'bg-gray-500';
    }
  };

  const formatDuration = (ms: number) => {
    if (ms < 1000) return `${ms}ms`;
    if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`;
    return `${(ms / 60000).toFixed(1)}m`;
  };

  const formatTimeAgo = (dateString: string) => {
    const now = new Date();
    const date = new Date(dateString);
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 1) return 'щойно';
    if (diffMins < 60) return `${diffMins}хв тому`;
    if (diffHours < 24) return `${diffHours}год тому`;
    return `${diffDays}д тому`;
  };

  if (loading && !tasks.length) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-pulse flex space-x-4">
          <div className="rounded-full bg-secondary-200 h-12 w-12"></div>
          <div className="flex-1 space-y-4 py-1">
            <div className="h-4 bg-secondary-200 rounded w-3/4"></div>
            <div className="space-y-2">
              <div className="h-4 bg-secondary-200 rounded"></div>
              <div className="h-4 bg-secondary-200 rounded w-5/6"></div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-error-50 border border-error-200 text-error-800 px-4 py-3 rounded relative" role="alert">
        <strong className="font-bold">Помилка!</strong>
        <span className="block sm:inline"> {error}</span>
      </div>
    );
  }

  return (
    <div className={`space-y-6 ${isInitialLoad ? 'animate-fade-in' : ''}`}>
      {/* Header */}
      <div className={`flex items-center justify-between ${isInitialLoad ? 'animate-slide-down' : ''}`}>
        <div>
          <h1 className="text-2xl font-bold text-secondary-900">Черга завдань</h1>
          <p className="text-secondary-600">Управління та моніторинг завдань системи</p>
        </div>
        <div className="flex items-center space-x-4">
          <select
            value={refreshInterval}
            onChange={(e) => setRefreshInterval(parseInt(e.target.value))}
            className="px-3 py-2 border border-secondary-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 transition-all duration-300"
          >
            <option value={2000}>2 секунди</option>
            <option value={5000}>5 секунд</option>
            <option value={10000}>10 секунд</option>
            <option value={30000}>30 секунд</option>
          </select>
        </div>
      </div>

      {/* Queue Statistics */}
      {queueStats && (
        <div className={`grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-6 ${isInitialLoad ? 'animate-slide-up' : ''}`}>
          <div className={`bg-white rounded-xl shadow-sm p-6 transform hover:scale-105 transition-all duration-300 hover:shadow-lg ${isInitialLoad ? 'animate-bounce-in' : ''}`} style={isInitialLoad ? {animationDelay: '0.1s'} : {}}>
            <div className="flex items-center">
              <div className="p-3 rounded-lg bg-primary-100 text-primary-600">
                <TasksIcon size="lg" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-secondary-600">Всього завдань</p>
                <p className="text-2xl font-bold text-secondary-900">{queueStats.total_tasks}</p>
              </div>
            </div>
          </div>

          <div className={`bg-white rounded-xl shadow-sm p-6 transform hover:scale-105 transition-all duration-300 hover:shadow-lg ${isInitialLoad ? 'animate-bounce-in' : ''}`} style={isInitialLoad ? {animationDelay: '0.2s'} : {}}>
            <div className="flex items-center">
              <div className="p-3 rounded-lg bg-yellow-100 text-yellow-600">
                <ClockIcon size="lg" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-secondary-600">В очікуванні</p>
                <p className="text-2xl font-bold text-secondary-900">{queueStats.pending_tasks}</p>
              </div>
            </div>
          </div>

          <div className={`bg-white rounded-xl shadow-sm p-6 transform hover:scale-105 transition-all duration-300 hover:shadow-lg ${isInitialLoad ? 'animate-bounce-in' : ''}`} style={isInitialLoad ? {animationDelay: '0.3s'} : {}}>
            <div className="flex items-center">
              <div className="p-3 rounded-lg bg-purple-100 text-purple-600">
                <ProcessingIcon size="lg" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-secondary-600">В обробці</p>
                <p className="text-2xl font-bold text-secondary-900">{queueStats.processing_tasks}</p>
              </div>
            </div>
          </div>

          <div className={`bg-white rounded-xl shadow-sm p-6 transform hover:scale-105 transition-all duration-300 hover:shadow-lg ${isInitialLoad ? 'animate-bounce-in' : ''}`} style={isInitialLoad ? {animationDelay: '0.4s'} : {}}>
            <div className="flex items-center">
              <div className="p-3 rounded-lg bg-success-100 text-success-600">
                <CheckIcon size="lg" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-secondary-600">Завершено</p>
                <p className="text-2xl font-bold text-secondary-900">{queueStats.completed_tasks}</p>
              </div>
            </div>
          </div>

          <div className={`bg-white rounded-xl shadow-sm p-6 transform hover:scale-105 transition-all duration-300 hover:shadow-lg ${isInitialLoad ? 'animate-bounce-in' : ''}`} style={isInitialLoad ? {animationDelay: '0.5s'} : {}}>
            <div className="flex items-center">
              <div className="p-3 rounded-lg bg-error-100 text-error-600">
                <AlertIcon size="lg" />
              </div>
              <div className="ml-4">
                <p className="text-sm font-medium text-secondary-600">Помилки</p>
                <p className="text-2xl font-bold text-secondary-900">{queueStats.failed_tasks}</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Queue Management */}
      {queueStats && (
        <div className={`bg-white rounded-xl shadow-sm p-6 ${isInitialLoad ? 'animate-slide-up' : ''}`} style={isInitialLoad ? {animationDelay: '0.6s'} : {}}>
          <h3 className="text-lg font-semibold text-secondary-900 mb-4">Управління чергами</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {queueStats.queue_sizes.critical !== undefined && (
              <div className="border rounded-lg p-4">
                <div className="flex items-center justify-between mb-2">
                  <h4 className="font-medium text-secondary-700">Критичний пріоритет</h4>
                  <span className="text-lg font-bold text-red-600">{queueStats.queue_sizes.critical}</span>
                </div>
                <div className="flex space-x-2">
                  <button
                    onClick={() => handleClearQueue('critical')}
                    className="px-3 py-1 text-xs bg-red-100 text-red-700 rounded hover:bg-red-200 transition-colors"
                  >
                    Очистити
                  </button>
                </div>
              </div>
            )}

            <div className="border rounded-lg p-4">
              <div className="flex items-center justify-between mb-2">
                <h4 className="font-medium text-secondary-700">Високий пріоритет</h4>
                <span className="text-lg font-bold text-orange-600">{queueStats.queue_sizes.high}</span>
              </div>
              <div className="flex space-x-2">
                <button
                  onClick={() => handleClearQueue('high')}
                  className="px-3 py-1 text-xs bg-orange-100 text-orange-700 rounded hover:bg-orange-200 transition-colors"
                >
                  Очистити
                </button>
              </div>
            </div>

            <div className="border rounded-lg p-4">
              <div className="flex items-center justify-between mb-2">
                <h4 className="font-medium text-secondary-700">Звичайний пріоритет</h4>
                <span className="text-lg font-bold text-blue-600">{queueStats.queue_sizes.normal}</span>
              </div>
              <div className="flex space-x-2">
                <button
                  onClick={() => handleClearQueue('normal')}
                  className="px-3 py-1 text-xs bg-blue-100 text-blue-700 rounded hover:bg-blue-200 transition-colors"
                >
                  Очистити
                </button>
              </div>
            </div>

            <div className="border rounded-lg p-4">
              <div className="flex items-center justify-between mb-2">
                <h4 className="font-medium text-secondary-700">Низький пріоритет</h4>
                <span className="text-lg font-bold text-green-600">{queueStats.queue_sizes.low}</span>
              </div>
              <div className="flex space-x-2">
                <button
                  onClick={() => handleClearQueue('low')}
                  className="px-3 py-1 text-xs bg-green-100 text-green-700 rounded hover:bg-green-200 transition-colors"
                >
                  Очистити
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Filters */}
              <div className={`bg-white rounded-xl shadow-sm p-6 ${isInitialLoad ? 'animate-slide-up' : ''}`} style={isInitialLoad ? {animationDelay: '0.7s'} : {}}>
        <h3 className="text-lg font-semibold text-secondary-900 mb-4">Фільтри</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4">
          <div>
            <label className="block text-sm font-medium text-secondary-700 mb-1">Статус</label>
            <select
              value={filters.status}
              onChange={(e) => setFilters(prev => ({ ...prev, status: e.target.value }))}
              className="w-full px-3 py-2 border border-secondary-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500"
            >
              <option value="all">Всі статуси</option>
              <option value="pending">В очікуванні</option>
              <option value="assigned">Призначено</option>
              <option value="processing">В обробці</option>
              <option value="completed">Завершено</option>
              <option value="failed">Помилка</option>
              <option value="timeout">Таймаут</option>
              <option value="cancelled">Скасовано</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-secondary-700 mb-1">Пріоритет</label>
            <select
              value={filters.priority}
              onChange={(e) => setFilters(prev => ({ ...prev, priority: e.target.value }))}
              className="w-full px-3 py-2 border border-secondary-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500"
            >
              <option value="all">Всі пріоритети</option>
              <option value="critical">Критичний</option>
              <option value="high">Високий</option>
              <option value="normal">Звичайний</option>
              <option value="low">Низький</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-secondary-700 mb-1">Тип завдання</label>
            <select
              value={filters.task_type}
              onChange={(e) => setFilters(prev => ({ ...prev, task_type: e.target.value }))}
              className="w-full px-3 py-2 border border-secondary-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500"
            >
              <option value="all">Всі типи</option>
              {uniqueTaskTypes.map(type => (
                <option key={type} value={type}>{type.replace('_', ' ')}</option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-secondary-700 mb-1">Воркер</label>
            <select
              value={filters.worker}
              onChange={(e) => setFilters(prev => ({ ...prev, worker: e.target.value }))}
              className="w-full px-3 py-2 border border-secondary-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500"
            >
              <option value="all">Всі воркери</option>
              {uniqueWorkers.map(worker => (
                <option key={worker} value={worker}>{worker}</option>
              ))}
            </select>
          </div>

          <div className="md:col-span-2">
            <label className="block text-sm font-medium text-secondary-700 mb-1">Пошук</label>
            <input
              type="text"
              value={filters.search}
              onChange={(e) => setFilters(prev => ({ ...prev, search: e.target.value }))}
              placeholder="Пошук по ID або типу завдання..."
              className="w-full px-3 py-2 border border-secondary-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500"
            />
          </div>
        </div>
      </div>

      {/* Tasks Table */}
              <div className={`bg-white rounded-xl shadow-sm overflow-hidden ${isInitialLoad ? 'animate-slide-up' : ''}`} style={isInitialLoad ? {animationDelay: '0.8s'} : {}}>
        <div className="px-6 py-4 border-b border-secondary-200">
          <h3 className="text-lg font-semibold text-secondary-900">
            Завдання ({filteredTasks.length})
          </h3>
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-secondary-200">
            <thead className="bg-secondary-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-secondary-500 uppercase tracking-wider">
                  ID / Тип
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-secondary-500 uppercase tracking-wider">
                  Статус
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-secondary-500 uppercase tracking-wider">
                  Пріоритет
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-secondary-500 uppercase tracking-wider">
                  Воркер
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-secondary-500 uppercase tracking-wider">
                  Прогрес
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-secondary-500 uppercase tracking-wider">
                  Час
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-secondary-500 uppercase tracking-wider">
                  Дії
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-secondary-200">
              {filteredTasks.map((task, index) => (
                <tr 
                  key={task.task_id}
                  className="hover:bg-secondary-50 transition-colors card-entrance"
                  style={{animationDelay: `${0.9 + index * 0.05}s`}}
                >
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div>
                      <div className="text-sm font-medium text-secondary-900">{task.task_id}</div>
                      <div className="text-sm text-secondary-500">{task.task_type.replace('_', ' ')}</div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getStatusColor(task.status)}`}>
                      {task.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center">
                      <div className={`w-2 h-2 rounded-full mr-2 ${getPriorityColor(task.priority)}`}></div>
                      <span className="text-sm text-secondary-900 capitalize">{task.priority}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-secondary-900">
                    {task.worker_name || task.assigned_worker || '-'}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    {task.status === 'processing' && task.progress !== undefined ? (
                      <div className="flex items-center">
                        <div className="w-16 bg-secondary-200 rounded-full h-2 mr-2">
                          <div 
                            className="bg-primary-600 h-2 rounded-full transition-all duration-300"
                            style={{ width: `${task.progress}%` }}
                          ></div>
                        </div>
                        <span className="text-xs text-secondary-600">{task.progress}%</span>
                      </div>
                    ) : (
                      <span className="text-sm text-secondary-500">-</span>
                    )}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-secondary-500">
                    <div>
                      <div>{formatTimeAgo(task.created_at)}</div>
                      {task.execution_time && (
                        <div className="text-xs text-secondary-400">
                          {formatDuration(task.execution_time)}
                        </div>
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                    <div className="flex space-x-2">
                      <button
                        onClick={() => {
                          setSelectedTask(task);
                          setShowTaskModal(true);
                        }}
                        className="text-primary-600 hover:text-primary-900 transition-colors"
                      >
                        Деталі
                      </button>
                      {task.status === 'failed' && task.retry_count < task.max_retries && (
                        <button
                          onClick={() => handleRetryTask(task.task_id)}
                          className="text-yellow-600 hover:text-yellow-900 transition-colors"
                        >
                          Повтор
                        </button>
                      )}
                      {['pending', 'assigned', 'processing'].includes(task.status) && (
                        <button
                          onClick={() => handleCancelTask(task.task_id)}
                          className="text-red-600 hover:text-red-900 transition-colors"
                        >
                          Скасувати
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Task Details Modal */}
      {showTaskModal && selectedTask && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
            <div className="px-6 py-4 border-b border-secondary-200 flex items-center justify-between">
              <h3 className="text-lg font-semibold text-secondary-900">
                Деталі завдання: {selectedTask.task_id}
              </h3>
              <button
                onClick={() => setShowTaskModal(false)}
                className="text-secondary-400 hover:text-secondary-600"
              >
                <CloseIcon size="lg" />
              </button>
            </div>
            <div className="px-6 py-4 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-secondary-700">Статус</label>
                  <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getStatusColor(selectedTask.status)}`}>
                    {selectedTask.status}
                  </span>
                </div>
                <div>
                  <label className="block text-sm font-medium text-secondary-700">Пріоритет</label>
                  <div className="flex items-center">
                    <div className={`w-2 h-2 rounded-full mr-2 ${getPriorityColor(selectedTask.priority)}`}></div>
                    <span className="text-sm text-secondary-900 capitalize">{selectedTask.priority}</span>
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-secondary-700">Тип завдання</label>
                  <p className="text-sm text-secondary-900">{selectedTask.task_type.replace('_', ' ')}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-secondary-700">Воркер</label>
                  <p className="text-sm text-secondary-900">{selectedTask.worker_name || selectedTask.assigned_worker || 'Не призначено'}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-secondary-700">Створено</label>
                  <p className="text-sm text-secondary-900">{new Date(selectedTask.created_at).toLocaleString('uk-UA')}</p>
                </div>
                {selectedTask.started_at && (
                  <div>
                    <label className="block text-sm font-medium text-secondary-700">Розпочато</label>
                    <p className="text-sm text-secondary-900">{new Date(selectedTask.started_at).toLocaleString('uk-UA')}</p>
                  </div>
                )}
                {selectedTask.completed_at && (
                  <div>
                    <label className="block text-sm font-medium text-secondary-700">Завершено</label>
                    <p className="text-sm text-secondary-900">{new Date(selectedTask.completed_at).toLocaleString('uk-UA')}</p>
                  </div>
                )}
                {selectedTask.execution_time && (
                  <div>
                    <label className="block text-sm font-medium text-secondary-700">Час виконання</label>
                    <p className="text-sm text-secondary-900">{formatDuration(selectedTask.execution_time)}</p>
                  </div>
                )}
                <div>
                  <label className="block text-sm font-medium text-secondary-700">Спроби</label>
                  <p className="text-sm text-secondary-900">{selectedTask.retry_count} / {selectedTask.max_retries}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-secondary-700">Таймаут</label>
                  <p className="text-sm text-secondary-900">{selectedTask.timeout}с</p>
                </div>
              </div>

              {selectedTask.error_message && (
                <div>
                  <label className="block text-sm font-medium text-secondary-700 mb-2">Помилка</label>
                  <div className="bg-red-50 border border-red-200 rounded-lg p-3">
                    <p className="text-sm text-red-800">{selectedTask.error_message}</p>
                  </div>
                </div>
              )}

              {selectedTask.task_data && (
                <div>
                  <label className="block text-sm font-medium text-secondary-700 mb-2">Дані завдання</label>
                  <div className="bg-secondary-50 border border-secondary-200 rounded-lg p-3">
                    <pre className="text-sm text-secondary-800 whitespace-pre-wrap">
                      {JSON.stringify(selectedTask.task_data, null, 2)}
                    </pre>
                  </div>
                </div>
              )}
            </div>
            <div className="px-6 py-4 border-t border-secondary-200 flex justify-end space-x-3">
              {selectedTask.status === 'failed' && selectedTask.retry_count < selectedTask.max_retries && (
                <button
                  onClick={() => {
                    handleRetryTask(selectedTask.task_id);
                    setShowTaskModal(false);
                  }}
                  className="px-4 py-2 bg-yellow-600 text-white rounded-lg hover:bg-yellow-700 transition-colors"
                >
                  Повторити
                </button>
              )}
              {['pending', 'assigned', 'processing'].includes(selectedTask.status) && (
                <button
                  onClick={() => {
                    handleCancelTask(selectedTask.task_id);
                    setShowTaskModal(false);
                  }}
                  className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
                >
                  Скасувати
                </button>
              )}
              <button
                onClick={() => setShowTaskModal(false)}
                className="px-4 py-2 bg-secondary-600 text-white rounded-lg hover:bg-secondary-700 transition-colors"
              >
                Закрити
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export { TasksView };
